CREATE TABLE oidc_clients (id TEXT PRIMARY KEY, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE oidc_redirect_uris (client_id TEXT NOT NULL REFERENCES oidc_clients(id) ON DELETE CASCADE, uri TEXT NOT NULL, PRIMARY KEY (client_id, uri));
CREATE TABLE authorization_codes (id UUID PRIMARY KEY, client_id TEXT NOT NULL REFERENCES oidc_clients(id), user_id UUID NOT NULL REFERENCES users(id), session_id UUID NOT NULL REFERENCES sessions(id), redirect_uri TEXT NOT NULL, pkce_challenge TEXT NOT NULL, nonce TEXT, scopes JSONB NOT NULL, audience TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, consumed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX authorization_codes_active_idx ON authorization_codes (expires_at) WHERE consumed_at IS NULL;
CREATE TABLE refresh_token_families (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), client_id TEXT NOT NULL REFERENCES oidc_clients(id), session_id UUID NOT NULL REFERENCES sessions(id), audience TEXT NOT NULL, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE refresh_tokens (id UUID PRIMARY KEY, family_id UUID NOT NULL REFERENCES refresh_token_families(id) ON DELETE CASCADE, secret_digest BYTEA NOT NULL, issued_at TIMESTAMPTZ NOT NULL DEFAULT now(), consumed_at TIMESTAMPTZ, UNIQUE (secret_digest));
